window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-080163659872db45"]={"versions": [{"id": "FIG-080163659872db45", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Schichtenmodell / Statisches Architektur-Blockdiagramm (BSW-Modulübersicht).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Kommunikationsstack (ComStack / Ethernet).\n</li><li><strong>Funktionaler Zweck:</strong> Verortung des BSW-Moduls <code>EthIf</code> (Ethernet Interface) als zentrale Abstraktionsschicht zwischen netzwerkbezogenen oberen Schichten (Protokoll- und State-Management) und den hardwarespezifischen Treibern der MCAL-/Transceiver-Ebene.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Obere Schicht (Upper Layer / Service Layer):</h5>\n<ul class=\"fig-list\"><li><strong><code>IP</code> (Internet Protocol):</strong> Vermittlungsschicht des TCP/IP-Stacks. Übergibt ausgehende IPv4/IPv6-Pakete an <code>EthIf</code> und empfängt geroutete Payloads anhand des Frame-Headers.\n</li><li><strong><code>ARP</code> (Address Resolution Protocol):</strong> Auflösung logischer IP-Adressen in physische MAC-Adressen. Nutzt <code>EthIf</code> für Sende- und Empfangsvorgänge dedizierter ARP-Frames (<code>EtherType 0x0806</code>).\n</li><li><strong><code>EthSM</code> (Ethernet State Manager):</strong> BSW-Modul zur Zustandsverwaltung (Modi: <code>ETHIF_MODE_DOWN</code>, <code>ETHIF_MODE_ACTIVE</code>). Steuert Netzwerk-Zustände in Koordination mit dem <code>ComM</code> (Communication Manager) und fordert Transceiver-/Controller-Moduswechsel über <code>EthIf</code> an.\n</li></ul>\n<h5 class=\"fig-section-h5\">Mittlere Abstraktionsschicht:</h5>\n<ul class=\"fig-list\"><li><strong><code>EthIf</code> (Ethernet Interface):</strong>\n<ul class=\"fig-list\"><li>Hardware-Abstraktionsinstanz.\n</li><li>Bündelt und virtualisiert darunterliegende Controller (<code>Eth</code>) und Transceiver (<code>EthTrcv</code>).\n</li><li>Übernimmt PDU-Routing/Demultiplexing anhand des IEEE 802.3 <code>EtherType</code> (<code>EthIf_RxIndication</code>).\n</li><li>Bildet logische Controller- und Transceiver-Indizes (<code>EthIfCtrlIdx</code>, <code>EthIfTrcvIdx</code>) auf physische Treiberinstanzen ab.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Untere Schicht (MCAL &amp; Hardware Abstraction / Drivers):</h5>\n<ul class=\"fig-list\"><li><strong><code>Eth</code> (Ethernet Driver):</strong> MCAL-Treiber zur direkten Ansteuerung des Ethernet-MAC-Controllers (DMA-Ringpuffer-Management, Frame-Transmission/-Reception, Pufferreservierung).\n</li><li><strong><code>EthTrcv</code> (Ethernet Transceiver Driver):</strong> Treiber für den Ethernet-PHY (Link-State-Überwachung, Auto-Negotiation, Wake-up/Sleep-Handling, PHY-Registerzugriff typischerweise via MII/MDIO oder SPI).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten:</h5>\n<ul class=\"fig-list\"><li><code>IP</code> / <code>ARP</code> / <code>EthSM</code> → <code>EthIf</code>: n:1 (mehrere Protokolle/Manager greifen auf eine gemeinsame Schnittstelle zu).\n</li><li><code>EthIf</code> → <code>Eth</code>: 1:n (Unterstützung mehrerer physischer MAC-Controller über logische Indizes).\n</li><li><code>EthIf</code> → <code>EthTrcv</code>: 1:m (Zuordnung von Transceivern zu Controllern; 1:1 oder unabhängige Transceiver-Instanzen).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Transmission (TX-Pfad):</strong>\n<ol class=\"fig-list\"><li><code>IP</code> / <code>ARP</code> fordert Sendepuffer via <code>EthIf_ProvideTxBuffer()</code> an.\n</li><li><code>EthIf</code> leitet den Request an den zugeordneten MAC-Treiber weiter (<code>Eth_ProvideTxBuffer()</code>).\n</li><li>Oberer Layer serialisiert Daten in den reservierten Puffer.\n</li><li>Sendeauslösung via <code>EthIf_Transmit()</code> mit Ziel-MAC und <code>EtherType</code>; Weiterleitung an <code>Eth_Transmit()</code>.\n</li><li>Asynchrone Sendebestätigung über Interrupt/Polling: <code>Eth_TxConfirmation()</code> → <code>EthIf_TxConfirmation()</code> → <code>IP/ARP</code>.\n</li></ol>\n</li><li><strong>Reception (RX-Pfad):</strong>\n<ol class=\"fig-list\"><li>Frame-Eingang am Controller triggert <code>Eth_RxIndication()</code> (aus ISR oder Polling-Hauptfunktion).\n</li><li>Weiterleitung an <code>EthIf_RxIndication()</code>.\n</li><li><code>EthIf</code> parst den Ethernet-Header (<code>EtherType</code>) und dispatcht die Payload synchron an die registrierte Callback-Funktion der Zielentität (<code>IP</code> oder <code>ARP</code>).\n</li></ol>\n</li><li><strong>Zustands- &amp; Link-Überwachung:</strong>\n<ol class=\"fig-list\"><li><code>EthSM</code> triggert Moduswechsel über <code>EthIf_SetControllerMode()</code>.\n</li><li><code>EthIf</code> synchronisiert/sequenziert Moduswechsel von MAC (<code>Eth_SetControllerMode</code>) und PHY (<code>EthTrcv_SetTransceiverMode</code>).\n</li><li>Zyklische Link-Statusabfrage via <code>EthIf_MainFunctionState()</code> ruft <code>EthTrcv_GetLinkState()</code> ab; Link-Änderungen werden an <code>EthSM</code> via <code>EthSM_TrcvLinkStateChg()</code> gemeldet.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Treiber-Entwickler (<code>Eth</code>, <code>EthTrcv</code>):</strong>\n<ul class=\"fig-list\"><li>Striktes Interface-Contracting: Treiber dürfen obere Schichten (<code>IP</code>, <code>ARP</code>, <code>EthSM</code>) niemals direkt referenzieren; Callbacks müssen ausnahmslos an <code>EthIf_*</code> gerichtet sein.\n</li><li>Reentrancy &amp; Pufferbehandlung: Puffer-Pointer aus <code>Eth_ProvideTxBuffer()</code> müssen bis zum Abschluss von <code>Eth_Transmit()</code> bzw. <code>Eth_TxConfirmation()</code> gelockt bleiben.\n</li></ul>\n</li><li><strong>Stack-Konfiguration (<code>EthIfConfig</code>):</strong>\n<ul class=\"fig-list\"><li>Konfiguration der Frame-Routing-Tabelle (<code>EthIfFrameOwnerConfig</code>): Zuordnung von <code>EtherType</code> (z. B. <code>0x0800</code> IPv4, <code>0x86DD</code> IPv6, <code>0x0806</code> ARP) zum Zielfunktionszeiger (<code>RxIndication</code>).\n</li><li>Zuordnung der physischen Hardware-IDs (<code>EthControllerId</code>, <code>EthTrcvId</code>) zu logischen <code>EthIfCtrlIdx</code>-Instanzen.\n</li></ul>\n</li><li><strong>Einschränkungen &amp; Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Im R4.0.3-Stand existiert noch kein Ethernet-Switch-Treiber (<code>EthSwt</code>) in dieser Abstraktionsebene (wurde erst in späteren Releases für TSN/Multi-Port-Switches standardisiert).\n</li><li>Nicht konfigurierte oder ungültige <code>EtherType</code>-Frames müssen von <code>EthIf</code> still verworfen oder optional an das <code>Det</code> gemeldet werden (<code>ETHIF_E_INV_PARAM</code>), ohne die RX-Pipeline zu blockieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9b643a22c788275d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Schichtenmodell / Statisches Architektur-Blockdiagramm (BSW-Modulübersicht).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Kommunikationsstack (ComStack / Ethernet).\n</li><li><strong>Funktionaler Zweck:</strong> Verortung des BSW-Moduls <code>EthIf</code> (Ethernet Interface) als zentrale Abstraktionsschicht zwischen netzwerkbezogenen oberen Schichten (Protokoll- und State-Management) und den hardwarespezifischen Treibern der MCAL-/Transceiver-Ebene.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Obere Schicht (Upper Layer / Service Layer):</h5>\n<ul class=\"fig-list\"><li><strong><code>TCP/IP</code> (TCP/IP Stack):</strong> Konsolidiertes Protokollstack-Modul (beinhaltet Transport- und Vermittlungsschicht wie TCP, UDP, IPv4/IPv6, ARP). Übergibt ausgehende Ethernet-Frames an <code>EthIf</code> und empfängt eingehende Payloads über registrierte Indikationen.\n</li><li><strong><code>EthSM</code> (Ethernet State Manager):</strong> BSW-Modul zur Verwaltung des Kommunikations- und Netzwerkzustands (z. B. <code>ETHIF_MODE_DOWN</code>, <code>ETHIF_MODE_ACTIVE</code>) in Abstimmung mit <code>ComM</code> und <code>EthIf</code>.\n</li><li><strong><code>CDD</code> (Complex Device Driver):</strong> Komplexer Treiber mit direktem Zugriff auf <code>EthIf</code>, um unter Umgehung des TCP/IP-Stacks proprietäre oder zeitsensitive Protokolle direkt über Ethernet abzuwickeln.\n</li></ul>\n<h5 class=\"fig-section-h5\">Mittlere Abstraktionsschicht:</h5>\n<ul class=\"fig-list\"><li><strong><code>EthIf</code> (Ethernet Interface):</strong>\n<ul class=\"fig-list\"><li>Hardware-Abstraktionsinstanz des Ethernet-Stacks.\n</li><li>Bündelt und virtualisiert darunterliegende Controller (<code>Eth</code>) und Transceiver (<code>EthTrcv</code>).\n</li><li>Übernimmt PDU-Routing und Frame-Demultiplexing anhand des IEEE 802.3 <code>EtherType</code> (<code>EthIf_RxIndication</code>).\n</li><li>Verwaltet logische Controller- und Transceiver-Indizes (<code>EthIfCtrlIdx</code>, <code>EthIfTrcvIdx</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Untere Schicht (MCAL &amp; Hardware Abstraction / Drivers):</h5>\n<ul class=\"fig-list\"><li><strong><code>Eth</code> (Ethernet Driver):</strong> MCAL-Treiber zur direkten Ansteuerung des Ethernet-MAC-Controllers (DMA-Ringpuffer, Frame-Senden/Empfangen, Pufferbereitstellung).\n</li><li><strong><code>EthTrcv</code> (Ethernet Transceiver Driver):</strong> Treiber für den Ethernet-PHY (Link-Status-Überwachung, Auto-Negotiation, Modussteuerung).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten:</h5>\n<ul class=\"fig-list\"><li><code>TCP/IP</code> / <code>EthSM</code> / <code>CDD</code> → <code>EthIf</code>: n:1 (mehrere obere Schichten greifen auf das gemeinsame Ethernet-Interface zu).\n</li><li><code>EthIf</code> → <code>Eth</code>: 1:n (EthIf bedient einen oder mehrere physische MAC-Controller).\n</li><li><code>EthIf</code> → <code>EthTrcv</code>: 1:m (Zuordnung von Transceivern zu Controllern).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Transmission (TX-Pfad):</strong>\n<ol class=\"fig-list\"><li><code>TCP/IP</code> oder <code>CDD</code> fordert Sendepuffer via <code>EthIf_ProvideTxBuffer()</code> an.\n</li><li><code>EthIf</code> leitet den Request an den zugeordneten MAC-Treiber weiter (<code>Eth_ProvideTxBuffer()</code>).\n</li><li>Oberer Layer serialisiert Nutzdaten in den bereitgestellten Puffer.\n</li><li>Sendeauslösung via <code>EthIf_Transmit()</code> unter Angabe von Ziel-MAC-Adresse und <code>EtherType</code>; Weiterleitung an <code>Eth_Transmit()</code>.\n</li><li>Asynchrone Sendebestätigung: <code>Eth_TxConfirmation()</code> → <code>EthIf_TxConfirmation()</code> → <code>TCP/IP</code> bzw. <code>CDD</code>.\n</li></ol>\n</li><li><strong>Reception (RX-Pfad):</strong>\n<ol class=\"fig-list\"><li>Frame-Eingang am MAC triggert <code>Eth_RxIndication()</code> (ISR oder Polling).\n</li><li>Weiterleitung an <code>EthIf_RxIndication()</code>.\n</li><li><code>EthIf</code> prüft den <code>EtherType</code> und leitet die Frame-Payload an den registrierten Callback der Zieleinheit weiter (<code>TCP/IP</code> oder <code>CDD</code>).\n</li></ol>\n</li><li><strong>Zustands- &amp; Link-Überwachung:</strong>\n<ol class=\"fig-list\"><li><code>EthSM</code> koordiniert Moduswechsel über <code>EthIf_SetControllerMode()</code>.\n</li><li><code>EthIf</code> steuert MAC (<code>Eth_SetControllerMode()</code>) und PHY (<code>EthTrcv_SetTransceiverMode()</code>) an.\n</li><li>Zyklische Link-Zustandsabfrage über <code>EthIf_MainFunctionState()</code> ruft <code>EthTrcv_GetLinkState()</code> ab; Änderungen werden an <code>EthSM</code> gemeldet.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Treiber- und Schichtentrennung (<code>Eth</code>, <code>EthTrcv</code>, <code>EthIf</code>):</strong>\n<ul class=\"fig-list\"><li>Treiber dürfen obere Schichten (<code>TCP/IP</code>, <code>EthSM</code>, <code>CDD</code>) niemals direkt referenzieren; Rückmeldungen und Indikationen müssen zwingend über <code>EthIf_*</code> erfolgen.\n</li><li>Puffer-Pointer aus <code>Eth_ProvideTxBuffer()</code> müssen bis zum Abschluss von <code>Eth_Transmit()</code> bzw. <code>Eth_TxConfirmation()</code> blockiert bleiben.\n</li></ul>\n</li><li><strong>Stack-Konfiguration (<code>EthIfConfig</code>):</strong>\n<ul class=\"fig-list\"><li>Zuordnungstabelle für <code>EtherType</code> (<code>EthIfFrameOwnerConfig</code>): Registrierung der Callbacks für <code>TCP/IP</code> sowie proprietäre <code>CDD</code>-EtherTypes.\n</li><li>Mapping logischer Controller- und Transceiver-IDs auf physische Treiberinstanzen.\n</li></ul>\n</li><li><strong>CDD-Integration:</strong>\n<ul class=\"fig-list\"><li>Der direkte Zugriff des <code>CDD</code> auf <code>EthIf</code> erfordert die Einhaltung standardisierter Pufferverwaltung und konfliktfreier <code>EtherType</code>-Registrierung.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-566d0fe1ece63760", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Schichtenmodell / Statisches Architektur-Blockdiagramm (BSW-Modulübersicht).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Kommunikationsstack (ComStack / Ethernet).\n</li><li><strong>Funktionaler Zweck:</strong> Verortung des BSW-Moduls <code>EthIf</code> (Ethernet Interface) als zentrale Abstraktionsschicht zwischen netzwerkbezogenen oberen Schichten (Protokoll- und State-Management) und den hardwarespezifischen Treibern der MCAL-/Transceiver-Ebene.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Obere Schicht (Upper Layer / Service Layer):</h5>\n<ul class=\"fig-list\"><li><strong><code>TCP/IP</code> (TCP/IP Stack):</strong> Protokollstack (TCP, UDP, IPv4/IPv6, ARP) zur Abwicklung internetbasierter Kommunikation über <code>EthIf</code>.\n</li><li><strong><code>EthSM</code> (Ethernet State Manager):</strong> Modul zur Verwaltung des Kommunikations- und Netzwerkzustands in Koordination mit <code>ComM</code> und <code>EthIf</code>.\n</li><li><strong><code>CDD</code> (Complex Device Driver):</strong> Direkter Nutzer von <code>EthIf</code> für proprietäre, latenzkritische oder nicht-IP-basierte Kommunikationsprotokolle.\n</li></ul>\n<h5 class=\"fig-section-h5\">Mittlere Abstraktionsschicht:</h5>\n<ul class=\"fig-list\"><li><strong><code>EthIf</code> (Ethernet Interface):</strong>\n<ul class=\"fig-list\"><li>Hardware-Abstraktionsinstanz des Ethernet-Stacks.\n</li><li>Bündelt und virtualisiert MAC-Controller (<code>Eth</code>), Transceiver (<code>EthTrcv</code>) und Switches (<code>EthSwt</code>).\n</li><li>Übernimmt PDU-Routing und Frame-Demultiplexing anhand des <code>EtherType</code> (<code>EthIf_RxIndication</code>).\n</li><li>Verwaltet logische Indizes für Controller (<code>EthIfCtrlIdx</code>), Transceiver (<code>EthIfTrcvIdx</code>) und Switch-Ports (<code>EthIfSwitchIdx</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Untere Schicht (MCAL &amp; Hardware Abstraction / Drivers):</h5>\n<ul class=\"fig-list\"><li><strong><code>Eth</code> (Ethernet Driver):</strong> MCAL-Treiber zur direkten Ansteuerung des Ethernet-MAC-Controllers (DMA-Ringpuffer, Sende-/Empfangspuffer).\n</li><li><strong><code>EthTrcv</code> (Ethernet Transceiver Driver):</strong> Treiber für den Ethernet-PHY (Link-State-Überwachung, Auto-Negotiation, Modussteuerung).\n</li><li><strong><code>EthSwt</code> (Ethernet Switch Driver):</strong> MCAL-/Hardware-Treiber zur Steuerung integrierter oder externer Ethernet-Switches (Port-Konfiguration, VLAN-Handling, Forwarding-Tabellen, Link-Status von Switch-Ports).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten:</h5>\n<ul class=\"fig-list\"><li><code>TCP/IP</code> / <code>EthSM</code> / <code>CDD</code> → <code>EthIf</code>: n:1 (obere Protokolle und Treiber greifen auf das zentrale Interface zu).\n</li><li><code>EthIf</code> → <code>Eth</code>: 1:n (Unterstützung mehrerer physischer MAC-Controller).\n</li><li><code>EthIf</code> → <code>EthTrcv</code>: 1:m (Zuordnung von Transceivern zu Controllern).\n</li><li><code>EthIf</code> → <code>EthSwt</code>: 1:k (Anbindung und Steuerung von Ethernet-Switches und deren Ports).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Transmission (TX-Pfad):</strong>\n<ol class=\"fig-list\"><li><code>TCP/IP</code> oder <code>CDD</code> fordert Sendepuffer via <code>EthIf_ProvideTxBuffer()</code> an.\n</li><li><code>EthIf</code> leitet die Anfrage an den zugeordneten MAC-Treiber weiter (<code>Eth_ProvideTxBuffer()</code>).\n</li><li>Nutzdaten werden in den Puffer serialisiert.\n</li><li>Sendeauslösung via <code>EthIf_Transmit()</code> mit Ziel-MAC und <code>EtherType</code>; Weiterleitung an <code>Eth_Transmit()</code> (ggf. mit Switch-Port-/VLAN-Tagging).\n</li><li>Asynchrone Sendebestätigung: <code>Eth_TxConfirmation()</code> → <code>EthIf_TxConfirmation()</code> → <code>TCP/IP</code> bzw. <code>CDD</code>.\n</li></ol>\n</li><li><strong>Reception (RX-Pfad):</strong>\n<ol class=\"fig-list\"><li>Frame-Eingang am MAC triggert <code>Eth_RxIndication()</code>.\n</li><li>Weiterleitung an <code>EthIf_RxIndication()</code>.\n</li><li><code>EthIf</code> analysiert Header (<code>EtherType</code>, VLAN) und dispatcht Frames synchron an <code>TCP/IP</code> oder <code>CDD</code>.\n</li></ol>\n</li><li><strong>Switch- und Link-Management:</strong>\n<ol class=\"fig-list\"><li><code>EthSM</code> koordiniert Netzwerk- und Port-Zustände über <code>EthIf</code>.\n</li><li><code>EthIf</code> steuert neben MAC (<code>Eth</code>) und Transceiver (<code>EthTrcv</code>) auch Switch-Ports und Switch-Zustände über <code>EthSwt</code> (<code>EthSwt_SetSwitchPortMode()</code>).\n</li><li>Zyklische Überwachung des Link-Zustands von Switch-Ports über <code>EthSwt</code> und PHYs über <code>EthTrcv</code>.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Switch-Integration (<code>EthSwt</code>):</strong>\n<ul class=\"fig-list\"><li>Mit der Einführung des <code>EthSwt</code> übernimmt <code>EthIf</code> die Abstraktion von Switch-Topologien und Port-zu-Controller-Verbindungen.\n</li><li>Switch-Management-Kommandos und Port-Statusabfragen dürfen nicht direkt von oberen Schichten, sondern ausschließlich über die <code>EthIf</code>-Switch-APIs ausgeführt werden.\n</li></ul>\n</li><li><strong>Treiber- und Schnittstellenanforderungen:</strong>\n<ul class=\"fig-list\"><li>Treiber (<code>Eth</code>, <code>EthTrcv</code>, <code>EthSwt</code>) dürfen obere Schichten nicht direkt referenzieren; Callbacks laufen ausnahmslos über <code>EthIf</code>.\n</li><li>Puffer-Pointer aus <code>Eth_ProvideTxBuffer()</code> bleiben bis zur Bestätigung via <code>Eth_TxConfirmation()</code> gelockt.\n</li></ul>\n</li><li><strong>Konfigurationsanforderungen (<code>EthIfConfig</code>):</strong>\n<ul class=\"fig-list\"><li>Konfiguration von Switch-Ports, Port-Gruppen und Zuordnungen von logischen Controllern zu Switch-Ports (<code>EthIfSwitchPortGroupRef</code>).\n</li><li>Zuordnungstabelle von <code>EtherType</code> zu Ziel-Callbacks (<code>EthIfFrameOwnerConfig</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5d4c46f7f24822bf", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Schichtenmodell / Statisches Architektur-Blockdiagramm (BSW-Modulübersicht).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Kommunikationsstack (ComStack / Ethernet).\n</li><li><strong>Funktionaler Zweck:</strong> Verortung des BSW-Moduls <code>EthIf</code> (Ethernet Interface) als zentrale Abstraktionsschicht zwischen netzwerkbezogenen oberen Schichten (Protokoll- und State-Management) und den hardwarespezifischen Treibern der MCAL-/Transceiver-Ebene.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Obere Schicht (Upper Layer / Service Layer):</h5>\n<ul class=\"fig-list\"><li><strong><code>TCP/IP</code> (TCP/IP Stack):</strong> Protokollstack (TCP, UDP, IPv4/IPv6, ARP) für kabelgebundene und IP-basierte Kommunikation.\n</li><li><strong><code>EthSM</code> (Ethernet State Manager):</strong> Modul zur Verwaltung des Kommunikations- und Netzwerkstatus in Abstimmung mit <code>ComM</code> und <code>EthIf</code>.\n</li><li><strong><code>V2X</code> (Vehicle-to-Everything Stack):</strong> BSW-Modulfamilie für Fahrzeug-Direktkommunikation (z. B. ETSI ITS / IEEE 802.11p / WAVE Protokolle wie GeoNetworking, BTP, CAM/DENM), die <code>EthIf</code> zur Datenübertragung nutzt.\n</li><li><strong><code>CDD</code> (Complex Device Driver):</strong> Direkter Nutzer von <code>EthIf</code> für proprietäre oder hardwarenahe Ethernet-Kommunikation.\n</li></ul>\n<h5 class=\"fig-section-h5\">Mittlere Abstraktionsschicht:</h5>\n<ul class=\"fig-list\"><li><strong><code>EthIf</code> (Ethernet Interface):</strong>\n<ul class=\"fig-list\"><li>Hardware-Abstraktionsinstanz für kabelgebundenes und drahtloses Ethernet.\n</li><li>Bündelt und virtualisiert drahtgebundene (<code>Eth</code>, <code>EthTrcv</code>), drahtlose (<code>WEth</code>, <code>WEthTrcv</code>) Treiber sowie Switches (<code>EthSwt</code>).\n</li><li>PDU-Routing und Frame-Demultiplexing anhand von <code>EtherType</code> und logischem Controller-Index.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Untere Schicht (MCAL &amp; Hardware Abstraction / Drivers):</h5>\n<ul class=\"fig-list\"><li><strong><code>Eth</code> (Ethernet Driver):</strong> MCAL-Treiber zur direkten Ansteuerung kabelgebundener Ethernet-MAC-Controller.\n</li><li><strong><code>EthTrcv</code> (Ethernet Transceiver Driver):</strong> Treiber für kabelgebundene Ethernet-PHYs.\n</li><li><strong><code>WEth</code> (Wireless Ethernet Driver):</strong> MCAL-Treiber zur Ansteuerung drahtloser Ethernet-MAC-Controller (z. B. WLAN / IEEE 802.11p).\n</li><li><strong><code>WEthTrcv</code> (Wireless Ethernet Transceiver Driver):</strong> Treiber für drahtlose Ethernet-Transceiver (RF-/PHY-Steuerung, Frequenz- und Kanalparameter).\n</li><li><strong><code>EthSwt</code> (Ethernet Switch Driver):</strong> Treiber zur Konfiguration und Überwachung von Ethernet-Switches und Switch-Ports.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten:</h5>\n<ul class=\"fig-list\"><li><code>TCP/IP</code> / <code>EthSM</code> / <code>V2X</code> / <code>CDD</code> → <code>EthIf</code>: n:1 (mehrere obere Schichten nutzen die gemeinsame Schnittstelle).\n</li><li><code>EthIf</code> → <code>Eth</code> / <code>WEth</code>: 1:n (EthIf bedient kabelgebundene und drahtlose MAC-Treiber).\n</li><li><code>EthIf</code> → <code>EthTrcv</code> / <code>WEthTrcv</code>: 1:m (Zuordnung kabelgebundener und drahtloser Transceiver).\n</li><li><code>EthIf</code> → <code>EthSwt</code>: 1:k (Anbindung von Ethernet-Switches).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Transmission (TX-Pfad):</strong>\n<ol class=\"fig-list\"><li><code>TCP/IP</code>, <code>V2X</code> oder <code>CDD</code> fordert Sendepuffer via <code>EthIf_ProvideTxBuffer()</code> unter Angabe des Ziel-Controller-Indexes (kabelgebunden oder drahtlos) an.\n</li><li><code>EthIf</code> leitet die Anforderung an den entsprechenden MAC-Treiber weiter (<code>Eth_ProvideTxBuffer()</code> bzw. <code>WEth_ProvideTxBuffer()</code>).\n</li><li>Nutzdaten werden in den Puffer serialisiert.\n</li><li>Sendeauslösung via <code>EthIf_Transmit()</code> mit Zieladresse und <code>EtherType</code>; Weiterleitung an <code>Eth_Transmit()</code> oder <code>WEth_Transmit()</code>.\n</li><li>Sendebestätigung: <code>Eth_TxConfirmation()</code> / <code>WEth_TxConfirmation()</code> → <code>EthIf_TxConfirmation()</code> → oberer Layer (<code>V2X</code>, <code>TCP/IP</code>, <code>CDD</code>).\n</li></ol>\n</li><li><strong>Reception (RX-Pfad):</strong>\n<ol class=\"fig-list\"><li>Eintreffende Frames an <code>Eth</code> oder <code>WEth</code> lösen <code>Eth_RxIndication()</code> bzw. <code>WEth_RxIndication()</code> aus.\n</li><li>Weiterleitung an <code>EthIf_RxIndication()</code>.\n</li><li><code>EthIf</code> filtert nach <code>EtherType</code> (z. B. GeoNetworking-EtherTypes für <code>V2X</code>, IP-EtherTypes für <code>TCP/IP</code>) und dispatcht an den registrierten Callback.\n</li></ol>\n</li><li><strong>Zustands- &amp; Transceiver-Management:</strong>\n<ol class=\"fig-list\"><li><code>EthSM</code> koordiniert Betriebsmodi über <code>EthIf</code>.\n</li><li><code>EthIf</code> steuert Controller (<code>Eth</code>, <code>WEth</code>), Transceiver (<code>EthTrcv</code>, <code>WEthTrcv</code>) und Switches (<code>EthSwt</code>) über einheitliche Schnittstellenfunktionen an.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Koexistenz drahtgebundener und drahtloser Medien:</strong>\n<ul class=\"fig-list\"><li><code>EthIf</code> abstrahiert kabelgebundenes Ethernet (<code>Eth</code>/<code>EthTrcv</code>) und Wireless Ethernet (<code>WEth</code>/<code>WEthTrcv</code>) über einheitliche Controller-Indizes (<code>EthIfCtrlIdx</code>).\n</li><li>Für <code>V2X</code>-Anwendungen müssen dedizierte Funkparameter und Controller-Instanzen im <code>EthIf</code> konfiguriert sein.\n</li></ul>\n</li><li><strong>Treiber- und Schnittstellenanforderungen:</strong>\n<ul class=\"fig-list\"><li>Treiber (<code>Eth</code>, <code>WEth</code>, <code>EthTrcv</code>, <code>WEthTrcv</code>, <code>EthSwt</code>) dürfen keine direkten Bezüge zu oberen Schichten aufweisen; Rückmeldungen erfolgen ausnahmslos über <code>EthIf</code>.\n</li><li>Puffer-Pointer aus Pufferanforderungen bleiben bis zur Bestätigung via TxConfirmation gebunden.\n</li></ul>\n</li><li><strong>Konfiguration (<code>EthIfConfig</code>):</strong>\n<ul class=\"fig-list\"><li>Frame-Routing-Tabelle zur Weiterleitung von V2X-Frames (z. B. EtherType <code>0x8947</code> für GeoNetworking) an das Modul <code>V2X</code>.\n</li><li>Zuordnung der physischen IDs drahtgebundener und drahtloser Controller/Transceiver zu logischen Indizes.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a991971c97438752", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Schichtenmodell / Statisches Architektur-Blockdiagramm (BSW-Modulübersicht).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Kommunikationsstack (ComStack / Ethernet).\n</li><li><strong>Funktionaler Zweck:</strong> Verortung des BSW-Moduls <code>EthIf</code> (Ethernet Interface) als zentrale Abstraktionsschicht zwischen netzwerkbezogenen oberen Schichten (Protokoll- und State-Management) und den hardwarespezifischen Treibern der MCAL-/Transceiver-Ebene.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Obere Schicht (Upper Layer / Service Layer):</h5>\n<ul class=\"fig-list\"><li><strong><code>TCP/IP</code> (TCP/IP Stack):</strong> Protokollstack (TCP, UDP, IPv4/IPv6, ARP) für kabelgebundene und IP-basierte Kommunikation.\n</li><li><strong><code>EthSM</code> (Ethernet State Manager):</strong> Modul zur Verwaltung des Kommunikations- und Netzwerkstatus in Abstimmung mit <code>ComM</code> und <code>EthIf</code>.\n</li><li><strong><code>V2X</code> (Vehicle-to-Everything Stack):</strong> BSW-Modulfamilie für Fahrzeug-Direktkommunikation (z. B. ETSI ITS / IEEE 802.11p / WAVE Protokolle wie GeoNetworking, BTP, CAM/DENM), die <code>EthIf</code> zur Datenübertragung nutzt.\n</li><li><strong><code>CDD</code> (Complex Device Driver):</strong> Direkter Nutzer von <code>EthIf</code> für proprietäre oder hardwarenahe Ethernet-Kommunikation.\n</li></ul>\n<h5 class=\"fig-section-h5\">Mittlere Abstraktionsschicht:</h5>\n<ul class=\"fig-list\"><li><strong><code>EthIf</code> (Ethernet Interface):</strong>\n<ul class=\"fig-list\"><li>Hardware-Abstraktionsinstanz für kabelgebundenes und drahtloses Ethernet.\n</li><li>Bündelt und virtualisiert drahtgebundene (<code>Eth</code>, <code>EthTrcv</code>), drahtlose (<code>WEth</code>, <code>WEthTrcv</code>) Treiber sowie Switches (<code>EthSwt</code>).\n</li><li>PDU-Routing und Frame-Demultiplexing anhand von <code>EtherType</code> und logischem Controller-Index.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Untere Schicht (MCAL &amp; Hardware Abstraction / Drivers):</h5>\n<ul class=\"fig-list\"><li><strong><code>Eth</code> (Ethernet Driver):</strong> MCAL-Treiber zur direkten Ansteuerung kabelgebundener Ethernet-MAC-Controller.\n</li><li><strong><code>EthTrcv</code> (Ethernet Transceiver Driver):</strong> Treiber für kabelgebundene Ethernet-PHYs.\n</li><li><strong><code>WEth</code> (Wireless Ethernet Driver):</strong> MCAL-Treiber zur Ansteuerung drahtloser Ethernet-MAC-Controller (z. B. WLAN / IEEE 802.11p).\n</li><li><strong><code>WEthTrcv</code> (Wireless Ethernet Transceiver Driver):</strong> Treiber für drahtlose Ethernet-Transceiver (RF-/PHY-Steuerung, Frequenz- und Kanalparameter).\n</li><li><strong><code>EthSwt</code> (Ethernet Switch Driver):</strong> Treiber zur Konfiguration und Überwachung von Ethernet-Switches und Switch-Ports.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten:</h5>\n<ul class=\"fig-list\"><li><code>TCP/IP</code> / <code>EthSM</code> / <code>V2X</code> / <code>CDD</code> → <code>EthIf</code>: n:1 (mehrere obere Schichten nutzen die gemeinsame Schnittstelle).\n</li><li><code>EthIf</code> → <code>Eth</code> / <code>WEth</code>: 1:n (EthIf bedient kabelgebundene und drahtlose MAC-Treiber).\n</li><li><code>EthIf</code> → <code>EthTrcv</code> / <code>WEthTrcv</code>: 1:m (Zuordnung kabelgebundener und drahtloser Transceiver).\n</li><li><code>EthIf</code> → <code>EthSwt</code>: 1:k (Anbindung von Ethernet-Switches).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Transmission (TX-Pfad):</strong>\n<ol class=\"fig-list\"><li><code>TCP/IP</code>, <code>V2X</code> oder <code>CDD</code> fordert Sendepuffer via <code>EthIf_ProvideTxBuffer()</code> unter Angabe des Ziel-Controller-Indexes (kabelgebunden oder drahtlos) an.\n</li><li><code>EthIf</code> leitet die Anforderung an den entsprechenden MAC-Treiber weiter (<code>Eth_ProvideTxBuffer()</code> bzw. <code>WEth_ProvideTxBuffer()</code>).\n</li><li>Nutzdaten werden in den Puffer serialisiert.\n</li><li>Sendeauslösung via <code>EthIf_Transmit()</code> mit Zieladresse und <code>EtherType</code>; Weiterleitung an <code>Eth_Transmit()</code> oder <code>WEth_Transmit()</code>.\n</li><li>Sendebestätigung: <code>Eth_TxConfirmation()</code> / <code>WEth_TxConfirmation()</code> → <code>EthIf_TxConfirmation()</code> → oberer Layer (<code>V2X</code>, <code>TCP/IP</code>, <code>CDD</code>).\n</li></ol>\n</li><li><strong>Reception (RX-Pfad):</strong>\n<ol class=\"fig-list\"><li>Eintreffende Frames an <code>Eth</code> oder <code>WEth</code> lösen <code>Eth_RxIndication()</code> bzw. <code>WEth_RxIndication()</code> aus.\n</li><li>Weiterleitung an <code>EthIf_RxIndication()</code>.\n</li><li><code>EthIf</code> filtert nach <code>EtherType</code> (z. B. GeoNetworking-EtherTypes für <code>V2X</code>, IP-EtherTypes für <code>TCP/IP</code>) und dispatcht an den registrierten Callback.\n</li></ol>\n</li><li><strong>Zustands- &amp; Transceiver-Management:</strong>\n<ol class=\"fig-list\"><li><code>EthSM</code> koordiniert Betriebsmodi über <code>EthIf</code>.\n</li><li><code>EthIf</code> steuert Controller (<code>Eth</code>, <code>WEth</code>), Transceiver (<code>EthTrcv</code>, <code>WEthTrcv</code>) und Switches (<code>EthSwt</code>) über einheitliche Schnittstellenfunktionen an.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Koexistenz drahtgebundener und drahtloser Medien:</strong>\n<ul class=\"fig-list\"><li><code>EthIf</code> abstrahiert kabelgebundenes Ethernet (<code>Eth</code>/<code>EthTrcv</code>) und Wireless Ethernet (<code>WEth</code>/<code>WEthTrcv</code>) über einheitliche Controller-Indizes (<code>EthIfCtrlIdx</code>).\n</li><li>Für <code>V2X</code>-Anwendungen müssen dedizierte Funkparameter und Controller-Instanzen im <code>EthIf</code> konfiguriert sein.\n</li></ul>\n</li><li><strong>Treiber- und Schnittstellenanforderungen:</strong>\n<ul class=\"fig-list\"><li>Treiber (<code>Eth</code>, <code>WEth</code>, <code>EthTrcv</code>, <code>WEthTrcv</code>, <code>EthSwt</code>) dürfen keine direkten Bezüge zu oberen Schichten aufweisen; Rückmeldungen erfolgen ausnahmslos über <code>EthIf</code>.\n</li><li>Puffer-Pointer aus Pufferanforderungen bleiben bis zur Bestätigung via TxConfirmation gebunden.\n</li></ul>\n</li><li><strong>Konfiguration (<code>EthIfConfig</code>):</strong>\n<ul class=\"fig-list\"><li>Frame-Routing-Tabelle zur Weiterleitung von V2X-Frames (z. B. EtherType <code>0x8947</code> für GeoNetworking) an das Modul <code>V2X</code>.\n</li><li>Zuordnung der physischen IDs drahtgebundener und drahtloser Controller/Transceiver zu logischen Indizes.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-260e9ae2926a32da", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Schichtenmodell / Statisches Architektur-Blockdiagramm (BSW-Modulübersicht).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Kommunikationsstack (ComStack / Ethernet).\n</li><li><strong>Funktionaler Zweck:</strong> Verortung des BSW-Moduls <code>EthIf</code> (Ethernet Interface) als zentrale Abstraktionsschicht zwischen netzwerkbezogenen oberen Schichten (Protokoll- und State-Management) und den hardwarespezifischen Treibern der MCAL-/Transceiver-Ebene.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Obere Schicht (Upper Layer / Service Layer):</h5>\n<ul class=\"fig-list\"><li><strong><code>TCP/IP</code> (TCP/IP Stack):</strong> Protokollstack für standardisierte IP-basierte Kommunikation über Ethernet.\n</li><li><strong><code>EthSM</code> (Ethernet State Manager):</strong> Modul zur Verwaltung des Kommunikations- und Netzwerkstatus in Abstimmung mit <code>ComM</code> und <code>EthIf</code>.\n</li><li><strong><code>V2X</code> (Vehicle-to-Everything Stack):</strong> BSW-Stack für V2X-Protokolle (z. B. ETSI ITS / IEEE 1609 / WLAN-basierte Direktkommunikation).\n</li><li><strong><code>CnV2x</code> (Cellular V2X Management / Connector):</strong> BSW-Modul zur Abwicklung und Verwaltung zellulärer V2X-Kommunikation (z. B. 3GPP C-V2X Sidelink / PC5) oberhalb von <code>EthIf</code>.\n</li><li><strong><code>CDD</code> (Complex Device Driver):</strong> Direkter Nutzer von <code>EthIf</code> für hardwarenahe oder proprietäre Protokolle.\n</li></ul>\n<h5 class=\"fig-section-h5\">Mittlere Abstraktionsschicht:</h5>\n<ul class=\"fig-list\"><li><strong><code>EthIf</code> (Ethernet Interface):</strong>\n<ul class=\"fig-list\"><li>Zentrale Hardware-Abstraktionsinstanz des Kommunikationsstacks.\n</li><li>Virtualisiert kabelgebundene (<code>Eth</code>, <code>EthTrcv</code>), Wireless- (<code>WEth</code>, <code>WEthTrcv</code>), Mobilfunk-/Cellular-V2X-Treiber (<code>CV2x</code>) sowie Switches (<code>EthSwt</code>).\n</li><li>Übernimmt PDU-Routing und Demultiplexing anhand von <code>EtherType</code> und logischem Controller-Index.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Untere Schicht (MCAL &amp; Hardware Abstraction / Drivers):</h5>\n<ul class=\"fig-list\"><li><strong><code>Eth</code> (Ethernet Driver):</strong> MCAL-Treiber zur Steuerung kabelgebundener MAC-Controller.\n</li><li><strong><code>EthTrcv</code> (Ethernet Transceiver Driver):</strong> Treiber für kabelgebundene Ethernet-PHYs.\n</li><li><strong><code>WEth</code> (Wireless Ethernet Driver):</strong> MCAL-Treiber zur Steuerung drahtloser MAC-Controller (WLAN / 802.11p).\n</li><li><strong><code>WEthTrcv</code> (Wireless Ethernet Transceiver Driver):</strong> Transceiver-Treiber für drahtlose Schnittstellen.\n</li><li><strong><code>CV2x</code> (Cellular V2X Driver):</strong> Hardwarenaher MCAL-/Treiber zur Anbindung von Mobilfunk-/C-V2X-Modems und -Transceivern an das Ethernet Interface.\n</li><li><strong><code>EthSwt</code> (Ethernet Switch Driver):</strong> Treiber zur Konfiguration und Steuerung von Ethernet-Switches und Switch-Ports.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten:</h5>\n<ul class=\"fig-list\"><li><code>TCP/IP</code> / <code>EthSM</code> / <code>V2X</code> / <code>CnV2x</code> / <code>CDD</code> → <code>EthIf</code>: n:1 (mehrere obere Schichten greifen auf das gemeinsame Interface zu).\n</li><li><code>EthIf</code> → <code>Eth</code> / <code>WEth</code> / <code>CV2x</code>: 1:n (Abstraktion diverser Hardware-Controller für Wired, Wireless und Cellular V2X).\n</li><li><code>EthIf</code> → <code>EthTrcv</code> / <code>WEthTrcv</code>: 1:m (Transceiver-Ansteuerung).\n</li><li><code>EthIf</code> → <code>EthSwt</code>: 1:k (Switch- und Port-Verwaltung).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Transmission (TX-Pfad):</strong>\n<ol class=\"fig-list\"><li>Obere Layer (<code>TCP/IP</code>, <code>V2X</code>, <code>CnV2x</code>, <code>CDD</code>) fordern Sendepuffer über <code>EthIf_ProvideTxBuffer()</code> unter Angabe des Ziel-Controller-Indexes an.\n</li><li><code>EthIf</code> delegiert die Anforderung an den entsprechenden Treiber (<code>Eth</code>, <code>WEth</code> oder <code>CV2x</code>).\n</li><li>Nutzdaten werden in den Puffer geschrieben.\n</li><li>Sendeauslösung via <code>EthIf_Transmit()</code> mit Zieladresse und <code>EtherType</code>; Weiterleitung an <code>Eth_Transmit()</code>, <code>WEth_Transmit()</code> bzw. <code>CV2x_Transmit()</code>.\n</li><li>Sendebestätigung: <code>Eth_TxConfirmation()</code> / <code>WEth_TxConfirmation()</code> / <code>CV2x_TxConfirmation()</code> → <code>EthIf_TxConfirmation()</code> → anforderndes oberes Modul.\n</li></ol>\n</li><li><strong>Reception (RX-Pfad):</strong>\n<ol class=\"fig-list\"><li>Eintreffende Frames an <code>Eth</code>, <code>WEth</code> oder <code>CV2x</code> triggern die jeweilige RxIndication an <code>EthIf</code> (<code>EthIf_RxIndication()</code>).\n</li><li><code>EthIf</code> filtert anhand des <code>EtherType</code> und Controller-Kontexts und leitet die Nutzdaten an <code>TCP/IP</code>, <code>V2X</code>, <code>CnV2x</code> oder <code>CDD</code> weiter.\n</li></ol>\n</li><li><strong>Zustands- &amp; Modus-Management:</strong>\n<ol class=\"fig-list\"><li><code>EthSM</code> steuert Modi über <code>EthIf</code>.\n</li><li><code>EthIf</code> synchronisiert Moduswechsel und Link-Zustände der kabelgebundenen, drahtlosen und zellulären Treiber sowie der Switches.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Integration von Cellular V2X (<code>CnV2x</code> / <code>CV2x</code>):</strong>\n<ul class=\"fig-list\"><li><code>EthIf</code> dient als Abstraktionsschicht für C-V2X-Kommunikation neben klassischem kabelgebundenen und Wireless-Ethernet.\n</li><li>C-V2X-Frames werden über spezifische logische Controller-Indizes und EtherTypes geroutet.\n</li></ul>\n</li><li><strong>Treiber- und Schnittstellenanforderungen:</strong>\n<ul class=\"fig-list\"><li>Sämtliche MCAL-Treiber (<code>Eth</code>, <code>WEth</code>, <code>CV2x</code>, <code>EthTrcv</code>, <code>WEthTrcv</code>, <code>EthSwt</code>) dürfen keine oberen Module direkt referenzieren; Kommunikation verläuft ausschließlich über <code>EthIf</code>.\n</li><li>Puffer-Pointer bleiben bis zur Ausführung von <code>TxConfirmation</code> gelockt.\n</li></ul>\n</li><li><strong>Konfiguration (<code>EthIfConfig</code>):</strong>\n<ul class=\"fig-list\"><li>Erweiterte Routing-Tabelle für C-V2X-spezifische EtherTypes und Weiterleitung an <code>CnV2x</code>.\n</li><li>Mapping logischer Controller-Instanzen auf physische <code>CV2x</code>-Treiberinstanzen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-080163659872db45", "to": "FIG-9b643a22c788275d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Obere Schicht: <code>IP</code> und <code>ARP</code> wurden durch das konsolidierte Protokollmodul <code>TCP/IP</code> ersetzt.\n</li><li>Obere Schicht: <code>CDD</code> (Complex Device Driver) wurde als neuer Kommunikationspartner oberhalb von <code>EthIf</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-9b643a22c788275d", "to": "FIG-566d0fe1ece63760", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Untere Schicht: <code>EthSwt</code> (Ethernet Switch Driver) wurde als Treiberbaustein unterhalb von <code>EthIf</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-566d0fe1ece63760", "to": "FIG-5d4c46f7f24822bf", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Obere Schicht: <code>V2X</code> (Vehicle-to-Everything) wurde als oberes Modul oberhalb von <code>EthIf</code> hinzugefügt.\n</li><li>Untere Schicht: <code>WEth</code> (Wireless Ethernet Driver) und <code>WEthTrcv</code> (Wireless Ethernet Transceiver Driver) wurden als Hardware-Treiber unterhalb von <code>EthIf</code> ergänzt.\n</li></ul>"}, {"from": "FIG-5d4c46f7f24822bf", "to": "FIG-a991971c97438752", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a991971c97438752", "to": "FIG-260e9ae2926a32da", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Obere Schicht: <code>CnV2x</code> (Cellular V2X) wurde als oberes Modul oberhalb von <code>EthIf</code> hinzugefügt.\n</li><li>Untere Schicht: <code>CV2x</code> (Cellular V2X Driver) wurde als Hardware-Treiber unterhalb von <code>EthIf</code> ergänzt.\n</li></ul>"}]};
